async () => {
  const fs = require('fs');
  const { exec } = require('child_process');
  const util = require('util');
  const execPromise = util.promisify(exec);

  try {
    // Check if playwright is installed
    const { stdout: version } = await execPromise('npx playwright --version');
    return `Playwright is installed: ${version}`;
  } catch (error) {
    try {
      // Try installing playwright browsers
      const { stdout } = await execPromise('npx playwright install-deps');
      return `Dependencies installed: ${stdout}`;
    } catch (installError) {
      return `Error with Playwright: ${installError.message}`;
    }
  }
}

async () => {
  const { exec } = require('child_process');
  const util = require('util');
  const execPromise = util.promisify(exec);

  try {
    // Check if git is available
    const { stdout } = await execPromise('git --version');
    return `Git is available: ${stdout}`;
  } catch (error) {
    return `Git is not available: ${error.message}`;
  }
}
